@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Cinzel:wght@400;500;600;700&display=swap');
:root{--bg:#101114;--panel:#17181d;--panel2:#1d1e24;--line:#34343b;--muted:#898991;--text:#eee9df;--gold:#d8b77b;--gold2:#f0d7a0;--teal:#7fc2bb;--red:#d46b68;--serif:'Cinzel',Georgia,serif;--sans:'DM Sans',system-ui,sans-serif}
*{box-sizing:border-box}html{background:#0b0c0f;color:var(--text);font-family:var(--sans);font-size:14px}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 70% 8%,#26252a 0,#121317 40%,#0d0e11 100%);-webkit-tap-highlight-color:transparent}.game-shell{min-height:100vh;max-width:1600px;margin:auto}.topbar{height:74px;border-bottom:1px solid #ffffff0d;display:flex;align-items:center;justify-content:space-between;padding:0 34px;background:#111216d9;position:relative;z-index:5}.brand{border:0;background:none;color:var(--text);display:flex;align-items:center;gap:12px;font:600 16px var(--serif);letter-spacing:2px;text-align:left;cursor:pointer}.brand-mark{font-size:27px;color:var(--gold);text-shadow:0 0 16px #b99458aa}.brand small{display:block;color:#82818a;font:600 8px var(--sans);letter-spacing:2px;margin-top:3px}.wallet{display:flex;align-items:center;gap:12px}.currency{height:34px;min-width:76px;padding:0 11px;border:1px solid #ffffff12;background:#1a1b20;border-radius:20px;display:flex;align-items:center;gap:8px;font-size:12px;font-weight:700;color:#e7dfd1}.currency b{font-size:14px;color:var(--gold)}.currency.gems b{color:#8fced9}.avatar-mini,.mobile-avatar{height:34px;width:34px;border-radius:50%;border:1px solid #b79865;background:#252329;color:#e8c98c;font-size:18px;cursor:pointer}.game-layout{display:grid;grid-template-columns:224px minmax(400px,1fr) 248px;max-width:1420px;margin:auto;min-height:calc(100vh - 74px)}.sidebar{border-right:1px solid #ffffff0d;padding:25px 16px 18px;display:flex;flex-direction:column}.player-card{display:grid;grid-template-columns:42px 1fr 30px;align-items:center;column-gap:10px;padding:0 4px 16px;border-bottom:1px solid #ffffff10}.player-crest{width:42px;height:42px;border:1px solid #9a7e58;border-radius:50%;display:grid;place-items:center;color:var(--gold2);font-size:20px;background:radial-gradient(circle,#65513a55,#16171c 70%);box-shadow:0 0 20px #c79d4a19}.player-ident{min-width:0}.player-ident strong{display:block;font:600 13px var(--serif);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.player-ident span{font-size:9px;color:#a49c8c;letter-spacing:1px}.level-badge{border:1px solid #54483a;border-radius:50%;height:28px;width:28px;display:grid;place-items:center;font-size:10px;color:var(--gold2)}.xp-track{grid-column:1/4;background:#302f34;height:3px;margin-top:13px;border-radius:3px;overflow:hidden}.xp-track i{display:block;height:100%;width:0;background:linear-gradient(90deg,#9d7747,#efd48e);transition:width .5s}.side-label{font-size:9px;font-weight:700;letter-spacing:2px;color:#72727b;margin:25px 9px 10px}.main-nav{display:grid;gap:5px}.nav-item{height:43px;padding:0 11px;border:0;background:none;border-radius:6px;color:#a8a8ad;text-align:left;display:flex;align-items:center;gap:12px;font:500 12px var(--sans);cursor:pointer;transition:.2s}.nav-item>span{width:17px;text-align:center;color:#aaa49a;font-size:16px}.nav-item i{margin-left:auto;color:#777;font-style:normal}.nav-item.active,.nav-item:hover{background:#29272a;color:#f1e8d8}.nav-item.active{box-shadow:inset 2px 0 var(--gold)}.nav-item.active>span{color:var(--gold)}.sidebar-bottom{margin-top:auto}.online-note{display:flex;gap:9px;align-items:center;padding:12px 9px;border-top:1px solid #ffffff0f}.status-dot,.live-dot{height:6px;width:6px;border-radius:50%;background:#c9a264;box-shadow:0 0 9px #ddbc75}.online-note b{font-size:9px;letter-spacing:1.2px;display:block;color:#c9c4b8}.online-note small{font-size:9px;color:#767780;display:block;margin-top:2px}.text-button{border:0;background:none;color:#b1a58f;font:500 10px var(--sans);padding:10px;cursor:pointer}.text-button span{color:var(--gold);padding-left:5px}.content-area{padding:27px clamp(20px,3vw,48px) 25px;min-width:0}.screen{display:none;animation:screenIn .28s ease}.screen.active{display:block}@keyframes screenIn{from{opacity:0;transform:translateY(6px)}to{opacity:1;transform:none}}.section-heading{display:flex;align-items:center;justify-content:space-between;margin:0 0 18px}.eyebrow{display:flex;align-items:center;gap:8px;color:#a79c88;font-size:9px;font-weight:700;letter-spacing:2px}.live-dot{background:#d9a565}.section-heading h1{font:500 clamp(23px,2.4vw,31px) var(--serif);margin:7px 0 0;letter-spacing:.5px}.section-heading h1 em{font-style:normal;color:var(--gold);font-size:.77em}.heading-dash{color:#58545a;font-size:.8em;margin:0 5px}.round-button{height:34px;width:34px;border:1px solid #ffffff17;background:#1c1d22;border-radius:50%;color:#b5a990;cursor:pointer}.battle-stage{height:clamp(355px,46vw,500px);min-height:355px;position:relative;overflow:hidden;border:1px solid #69605a66;border-radius:9px;background:linear-gradient(180deg,#141b23 0%,#283137 38%,#465047 70%,#1e2926 100%);isolation:isolate;box-shadow:0 12px 45px #0005,inset 0 0 70px #08090d80}.stage-sky{position:absolute;inset:0;background:radial-gradient(ellipse at 58% 17%,#ac969034 0,transparent 29%),linear-gradient(180deg,#161c27a6,#29352f21 70%)}.moon-halo{position:absolute;width:135px;height:135px;top:36px;right:20%;border-radius:50%;background:#e5d7b51a;filter:blur(16px)}.moon{position:absolute;right:calc(20% + 24px);top:56px;width:51px;height:51px;border-radius:50%;background:radial-gradient(circle at 35% 35%,#f0e2c5,#b9ae9d 68%,#797c7c);box-shadow:0 0 22px #d5c8a644,0 0 75px #d1c5aa27;opacity:.84}.distant-mountains{position:absolute;inset:40% -8% 15%;background:#242c2b;clip-path:polygon(0 72%,10% 47%,18% 66%,29% 26%,41% 65%,55% 22%,68% 63%,77% 36%,91% 70%,100% 44%,100% 100%,0 100%);opacity:.73}.distant-mountains:after{content:'';position:absolute;inset:25% 0 0;background:#303a34;clip-path:polygon(0 62%,15% 34%,29% 69%,49% 28%,64% 57%,77% 31%,91% 63%,100% 40%,100% 100%,0 100%);opacity:.62}.pine{position:absolute;bottom:15%;width:145px;height:310px;opacity:.68;filter:drop-shadow(0 2px 6px #101610)}.pine:before{content:'';position:absolute;inset:0;background:#101a18;clip-path:polygon(50% 0,72% 27%,63% 25%,86% 49%,71% 46%,100% 73%,65% 68%,68% 100%,31% 100%,35% 68%,0 74%,27% 47%,12% 50%,38% 26%,28% 28%)}.pine-a{left:-36px;height:285px;width:132px}.pine-b{right:-15px;height:365px;width:174px}.pine-c{left:16%;height:228px;width:103px;opacity:.37}.ground-mist{position:absolute;left:0;right:0;bottom:12%;height:31%;background:radial-gradient(ellipse at 48% 75%,#c0c6a328,transparent 60%);filter:blur(9px)}.stage-vignette{position:absolute;inset:0;box-shadow:inset 0 0 75px #07090caa;pointer-events:none}.stage-caption{position:absolute;top:17px;left:18px;right:18px;z-index:2;display:flex;align-items:center;gap:8px;color:#d4c8ae;font-size:8px;font-weight:700;letter-spacing:1.5px;text-shadow:0 1px 5px #000}.location-pin{color:var(--gold);font-size:15px}.caption-line{height:1px;width:22px;background:#b9a37566}.combatant{position:absolute;z-index:2;bottom:19%;display:flex;flex-direction:column;align-items:center;transition:filter .15s}.hero-combatant{left:14%;width:clamp(112px,17vw,160px)}.enemy-combatant{right:12%;width:clamp(138px,19vw,182px)}.hero-art{width:100%;height:auto;overflow:visible;filter:drop-shadow(0 9px 9px #090a0d99)}.enemy-art{width:100%;height:auto;overflow:visible;filter:drop-shadow(0 10px 11px #080b09aa)}.hero-aura{position:absolute;bottom:7%;width:135%;height:40%;border-radius:50%;background:radial-gradient(ellipse,#c3a86f2a,transparent 67%);filter:blur(8px)}.enemy-glow{position:absolute;bottom:8%;width:140%;height:45%;border-radius:50%;background:radial-gradient(ellipse,#8ba65b2b,transparent 65%);filter:blur(8px)}.hero-shadow,.enemy-shadow{position:absolute;bottom:-3px;height:18px;width:75%;border-radius:50%;background:#0709096b;filter:blur(7px)}.figure-label{position:relative;z-index:4;text-align:center;margin-top:-3px;text-shadow:0 2px 5px #000}.figure-label b{display:block;font:600 10px var(--serif);letter-spacing:.4px}.figure-label small{display:block;font-size:7px;color:#c2b699;letter-spacing:1px;margin-top:3px}.enemy-label b{color:#e2d9c6}.enemy-label small{color:#c79b75}.enemy-hud{position:absolute;top:50px;left:50%;transform:translateX(-50%);width:min(270px,54%);z-index:4}.enemy-topline,.health-meta{display:flex;align-items:center;justify-content:space-between;color:#e0d9ce;font-size:8px;letter-spacing:1px}.enemy-topline{font-weight:700;margin-bottom:6px;text-shadow:0 1px 5px #000}.enemy-topline span:last-child{color:#d4bd90}.health-track{height:7px;background:#15171a;border:1px solid #ffffff25;border-radius:8px;overflow:hidden;box-shadow:0 2px 4px #0007}.health-track i{display:block;height:100%;border-radius:8px;transition:width .34s cubic-bezier(.2,.8,.2,1)}.enemy-health i{background:linear-gradient(90deg,#923f43,#df7770);box-shadow:0 0 9px #d65e5e66}.health-meta{margin-top:4px;color:#d2c8bc;font-size:8px;letter-spacing:.3px}.hero-hud{position:absolute;bottom:16px;left:17px;width:175px;z-index:4;text-shadow:0 1px 5px #000}.hero-hud-top{display:flex;justify-content:space-between;align-items:end;margin-bottom:6px}.hero-hud-top b{display:block;font:600 10px var(--serif)}.hero-hud-top small{display:block;color:#d2c6af;font-size:7px;letter-spacing:.6px;margin-top:2px}.hp-number{font-size:8px;color:#e0d6c6}.hero-health{height:5px}.hero-health i{background:linear-gradient(90deg,#477a65,#8cca9b)}.resource-track{height:3px;background:#171922;margin-top:4px;border-radius:4px;overflow:hidden}.resource-track i{display:block;height:100%;width:100%;background:linear-gradient(90deg,#496ac3,#96b9f4);transition:width .3s}.resource-label{display:flex;justify-content:space-between;color:#c7c3ba;font-size:6px;letter-spacing:1px;margin-top:4px}.hit-flash{position:absolute;z-index:3;inset:0;background:#fff2;opacity:0;pointer-events:none}.hit-flash.show{animation:flash .28s ease-out}@keyframes flash{0%{opacity:.6}100%{opacity:0}}.damage-layer{position:absolute;inset:0;z-index:6;pointer-events:none}.damage-number{position:absolute;font:700 19px var(--serif);color:#ffd98e;text-shadow:0 2px 7px #120c07,0 0 11px #f1844a88;animation:floatDamage .95s ease-out forwards;white-space:nowrap}.damage-number.crit{font-size:25px;color:#fff0a5}.damage-number.heal{color:#8eecb1}.damage-number.enemy-damage{color:#f18a7f}@keyframes floatDamage{0%{opacity:0;transform:translate(-50%,10px) scale(.8)}15%{opacity:1;transform:translate(-50%,0) scale(1.15)}100%{opacity:0;transform:translate(-50%,-55px) scale(.95)}}.battle-info{display:flex;justify-content:space-between;align-items:center;padding:14px 2px 12px;border-bottom:1px solid #ffffff10}.enemy-intro{display:flex;align-items:center;gap:10px}.beast-icon{height:32px;width:32px;border:1px solid #7d765e;border-radius:7px;background:#292c28;display:grid;place-items:center;color:#c6a96d;font-size:18px}.enemy-intro strong{font:600 11px var(--serif);display:block}.enemy-intro small{display:block;color:#86868b;font-size:9px;margin-top:3px}.reward-preview{text-align:right}.reward-preview>span{display:block;color:#777780;font-size:7px;font-weight:700;letter-spacing:1.2px;margin-bottom:5px}.reward-preview b{font-size:9px;color:#d9cdb7}.reward-preview b:first-letter{color:var(--gold)}.reward-preview i{font-style:normal;color:#69656a;margin:0 3px}.combat-controls{padding-top:12px}.skill-row{display:grid;grid-template-columns:1fr 1fr;gap:9px}.skill-button{height:50px;border:1px solid #ffffff12;border-radius:6px;background:linear-gradient(135deg,#24232a,#1b1b20);display:flex;align-items:center;text-align:left;color:#ded9cf;padding:0 10px;gap:8px;cursor:pointer;position:relative;transition:.2s}.skill-button:hover:not(:disabled){border-color:#9c7d52;background:#29262a}.skill-button:disabled{opacity:.45;cursor:not-allowed}.skill-icon{height:29px;width:29px;display:grid;place-items:center;color:#eccb88;background:#423b31;border:1px solid #886d43;border-radius:5px;font-size:17px}.skill-icon.violet{color:#c9a9ef;background:#373044;border-color:#766294}.skill-button b{display:block;font-size:9px}.skill-button small{display:block;font-size:7px;color:#939097;margin-top:3px;letter-spacing:.2px}.skill-key{margin-left:auto;align-self:flex-start;margin-top:5px;font-style:normal;font-size:8px;color:#79767b}.action-row{display:grid;grid-template-columns:1fr 78px;gap:9px;margin-top:9px}.attack-button{height:60px;border:1px solid #c9a268;background:linear-gradient(100deg,#73563a,#4c3b32 62%,#332c2e);border-radius:6px;color:#f6e5c4;display:flex;align-items:center;gap:12px;padding:0 16px;text-align:left;cursor:pointer;box-shadow:0 4px 18px #986d3022,inset 0 1px #fff2;transition:transform .12s,filter .2s}.attack-button:active{transform:scale(.985);filter:brightness(1.25)}.attack-button:disabled{opacity:.45;cursor:not-allowed}.sword-icon{font-size:25px;color:#f1d89e;text-shadow:0 0 12px #fff4}.attack-button b{display:block;font:700 13px var(--serif);letter-spacing:2px}.attack-button small{display:block;font-size:8px;color:#d5c4a4;margin-top:2px}.attack-chevron{margin-left:auto;font-size:23px;color:#e8c985}.potion-button{border:1px solid #ffffff16;background:#202025;border-radius:6px;color:#d9d4ca;display:flex;flex-direction:row;align-items:center;justify-content:center;gap:4px;cursor:pointer;font-size:10px}.potion-button>span{font-size:17px;color:#dc8177}.potion-button b{font-size:8px;letter-spacing:.4px}.potion-button small{position:absolute;transform:translate(24px,19px);font-size:7px;color:#8f8b8b}.continue-button{width:100%;height:48px;margin-top:9px;border:1px solid #b89a65;background:linear-gradient(95deg,#55452e,#44372e);color:#f0dbaf;font:700 10px var(--sans);letter-spacing:1.1px;border-radius:5px;cursor:pointer}.continue-button span{margin-left:8px}.hidden{display:none!important}.battle-footnote{text-align:center;color:#77767a;font-size:8px;margin:12px 0 0;letter-spacing:.3px}.battle-footnote span{color:#b89660;margin-right:4px}.hero-combatant.attack{animation:heroLunge .42s ease}.enemy-combatant.hit{animation:enemyHit .33s ease}.enemy-combatant.attack{animation:enemyLunge .4s ease}.hero-combatant.hurt{animation:heroHurt .34s ease}@keyframes heroLunge{0%,100%{transform:translateX(0)}45%{transform:translateX(42px) translateY(-4px) scale(1.04)}}@keyframes enemyHit{0%,100%{transform:translateX(0);filter:brightness(1)}35%{transform:translateX(12px);filter:brightness(1.7) sepia(.35)}}@keyframes enemyLunge{0%,100%{transform:translateX(0)}45%{transform:translateX(-28px) translateY(-4px)}}@keyframes heroHurt{0%,100%{filter:none}35%{filter:brightness(1.8) sepia(1) hue-rotate(320deg)}}.skill-burst{position:absolute;z-index:5;left:65%;top:48%;width:90px;height:90px;border:2px solid #e6c27f;border-radius:50%;transform:translate(-50%,-50%) scale(.25);opacity:0;pointer-events:none}.skill-burst.show{animation:burst .55s ease-out}@keyframes burst{0%{opacity:1;transform:translate(-50%,-50%) scale(.2);box-shadow:0 0 0 0 #f4d28a88}60%{opacity:.9;border-color:#e5b7f4;box-shadow:0 0 50px 20px #c798e766}100%{opacity:0;transform:translate(-50%,-50%) scale(2.2)}}.right-rail{border-left:1px solid #ffffff0d;padding:31px 18px}.rail-title{display:flex;align-items:center;justify-content:space-between;color:#88878c;font-size:8px;font-weight:700;letter-spacing:1.5px;margin-bottom:16px}.rail-title>span{color:var(--gold);font-size:14px}.rail-title button{border:0;background:none;color:#c7ad7c;font-size:8px;letter-spacing:.5px;cursor:pointer}.rail-quest{background:linear-gradient(145deg,#222126,#191a1f);border:1px solid #ffffff12;border-radius:7px;padding:12px;display:grid;grid-template-columns:30px 1fr;column-gap:9px}.quest-icon{width:28px;height:28px;background:#40372d;border:1px solid #78654a;border-radius:5px;display:grid;place-items:center;color:#e1c48b}.rail-quest small{color:#bc9f69;font-size:7px;font-weight:700;letter-spacing:1px;display:block}.rail-quest b{display:block;font:600 10px var(--serif);margin-top:4px}.rail-quest p{font-size:8px;color:#99979a;margin:5px 0 11px}.quest-progress{grid-column:1/3;height:3px;border-radius:4px;background:#35343a;overflow:hidden}.quest-progress i{height:100%;width:0;background:#c8a86d;display:block;transition:width .4s}.quest-count{grid-column:1/3;text-align:right;font-size:8px;color:#a8a5a2;margin-top:5px}.rail-divider{height:1px;background:#ffffff11;margin:22px 0}.gear-preview{display:grid;grid-template-columns:1fr 1fr;gap:7px}.gear-cell{height:69px;border:1px solid #ffffff12;border-radius:5px;background:#1a1b20;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;position:relative}.gear-cell .gear-glyph{font-size:20px;color:#a7a3a0}.gear-cell small{font-size:7px;color:#818087;letter-spacing:.6px}.gear-cell.filled .gear-glyph{color:var(--gold)}.gear-cell.filled{border-color:#98784c66;background:linear-gradient(145deg,#28252a,#1a1b20)}.rail-tip{margin-top:22px;padding:11px 10px;border-left:1px solid #806c4c;background:linear-gradient(90deg,#26231e,#18191e)}.rail-tip span{color:#b89a65;font:20px var(--serif)}.rail-tip p{font:italic 10px/1.6 var(--serif);color:#b5aea2;margin:5px 0 0}.mobile-heading,.bottom-nav{display:none}
