const baseState = () => ({hero:null,region:0,encounter:1,enemyHp:120,enemyMax:120,heroHp:180,mana:60,gold:60,gems:8,xp:0,level:1,points:0,stats:{Might:0,Vitality:0,Focus:0},inventory:[],equipment:{},potions:2,kills:0,questKills:0,unlocked:0,bosses:[],victory:false,filter:'All',created:false,cosmetics:[]});
let state = loadState();
function loadState(){try{const raw=localStorage.getItem('aetheria-save-v1');if(!raw)return baseState();return {...baseState(),...JSON.parse(raw)}}catch{return baseState()}}
function save(silent=false){try{localStorage.setItem('aetheria-save-v1',JSON.stringify(state));if(!silent)toast('Progress saved on this device.')}catch{toast('Unable to save on this device.')};renderTop()}
let toastTimer;
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2300)}
function heroStats(){const c=classes[state.hero?.class||'Warrior'];const gear=Object.values(state.equipment).filter(Boolean).reduce((a,it)=>a+(it.power||0),0);return {hp:c.hp+state.stats.Vitality*12+state.level*8+gear*2,mana:c.mana+state.stats.Focus*8,attack:c.attack+state.stats.Might*2+Math.floor(state.level*1.6)+gear}}
function requiredXp(level=state.level){return 45+level*30}
function renderTop(){if(!state.hero)return;$('#goldCount').textContent=state.gold;$('#gemCount').textContent=state.gems;$('#sidebarName').textContent=state.hero.name;$('#sidebarClass').textContent=`${state.hero.class.toUpperCase()} · LV ${state.level}`;$('#sidebarLevel').textContent=String(state.level).padStart(2,'0');$('#sidebarCrest').textContent=state.hero.faction==='Angels'?'✧':'☾';$('#sidebarXp').style.width=`${Math.min(100,state.xp/requiredXp()*100)}%`;$('#bagCount').textContent=state.inventory.length;$('#heroNameLabel').textContent=state.hero.name;$('#heroClassLabel').textContent=classes[state.hero.class].role;$('#battleHeroName').textContent=state.hero.name;$('#battleHeroClass').textContent=`LV ${state.level} · ${state.hero.class.toUpperCase()}`;$('#regionHeading').textContent=regions[state.region].name;$('#regionCaption').textContent=regions[state.region].name.toUpperCase()==='GREENDALE'?'THE OLD GLADE':regions[state.region].name.toUpperCase();$('#encounterCount').textContent=`ENCOUNTER ${String(state.encounter).padStart(2,'0')}`;$('#questCount').textContent=`${Math.min(3,state.questKills)} / 3`;$('#questProgress').style.width=`${Math.min(100,state.questKills/3*100)}%`;renderGearPreview();}
function enemyForCurrent(){if(state.region===0){const ix=state.encounter>=6?4:state.encounter>=4?3:(state.encounter-1)%3;return foes[ix]}const r=regions[state.region];if(state.encounter>=6)return {name:r.boss,title:'REGIONAL BOSS',desc:`The ruler of ${r.name} blocks the way forward`,hp:800+state.region*220,xp:180+state.region*35,gold:180+state.region*40,icon:r.icon,boss:true};if(state.encounter>=4)return {name:`${r.name} Elite`,title:'ELITE · CHAMPION',desc:`A fearsome guardian of ${r.name}`,hp:360+state.region*90,xp:65+state.region*12,gold:52+state.region*10,icon:r.icon,elite:true};const names=[`${r.name} Lurker`,`${r.name} Shade`,`${r.name} Ravager`];return {name:names[(state.encounter-1)%3],title:'WILD · FIEND',desc:`A creature warped by the ${r.name}`,hp:180+state.region*35,xp:27+state.region*6,gold:19+state.region*4,icon:r.icon}}
function resetEnemy(){const e=enemyForCurrent();state.enemyMax=e.hp+Math.floor((state.encounter-1)*7);state.enemyHp=state.enemyMax;state.victory=false;renderBattle();save(true)}
function renderBattle(){if(!state.hero)return;const e=enemyForCurrent();if(state.enemyMax<=0||state.enemyHp<=0&&!state.victory){state.enemyMax=e.hp;state.enemyHp=e.hp}$('#enemyNameLabel').textContent=e.name;$('#enemyIntroName').textContent=e.name;$('#enemyIntroDesc').textContent=e.desc;$('#enemyTypeLabel').textContent=e.title;$('#enemyKind').textContent=e.title;$('#enemyLevel').textContent=`LV. ${Math.max(1,state.level+Math.floor(state.encounter/2))}${e.boss?' · BOSS':e.elite?' · ELITE':''}`;$('#enemyHpText').textContent=`${Math.max(0,state.enemyHp)} / ${state.enemyMax}`;$('#enemyHpPercent').textContent=`${Math.round(Math.max(0,state.enemyHp)/state.enemyMax*100)}%`;$('#enemyHealthBar').style.width=`${Math.max(0,state.enemyHp)/state.enemyMax*100}%`;$('#heroHpText').textContent=`${state.heroHp} / ${heroStats().hp}`;$('#heroHealthBar').style.width=`${Math.max(0,state.heroHp)/heroStats().hp*100}%`;$('#manaText').textContent=`MANA ${state.mana} / ${heroStats().mana}`;$('#manaBar').style.width=`${state.mana/heroStats().mana*100}%`;
 $('#xpPreview').textContent=e.xp;$('#goldPreview').textContent=e.gold;$('#potionCount').textContent=`× ${state.potions}`;const c=classes[state.hero.class];$('#skillOneName').textContent=c.skill1;$('#skillTwoName').textContent=c.skill2;$('#skillOneMeta').textContent='12 MANA · 2× DMG';$('#skillTwoMeta').textContent='20 MANA · 3× DMG';$('#attackButton').disabled=state.victory;$('#skillOne').disabled=state.victory||state.mana<12;$('#skillTwo').disabled=state.victory||state.mana<20;$('#potionButton').disabled=state.potions<=0||state.heroHp>=heroStats().hp;$('#continueButton').classList.toggle('hidden',!state.victory);$('#attackButton').classList.toggle('hidden',state.victory);$('.skill-row').classList.toggle('hidden',state.victory);$('#enemyFigure').style.filter=e.boss?'drop-shadow(0 0 15px #e3b97755)':e.elite?'drop-shadow(0 0 11px #d88b7055)':'';renderTop()}
