function damageText(text,x,y,type=''){const el=document.createElement('div');el.className=`damage-number ${type}`;el.textContent=text;el.style.left=`${x}%`;el.style.top=`${y}%`;$('#damageLayer').append(el);setTimeout(()=>el.remove(),1050)}
function attack(mult=1,skill=0){if(state.victory)return;const e=enemyForCurrent();if(skill){const cost=skill===1?12:20;if(state.mana<cost){toast('Not enough mana.');return}state.mana-=cost}let damage=Math.round((heroStats().attack*(mult===1?1.05:mult))*(.9+Math.random()*.23));if(e.boss)damage=Math.round(damage*.9);state.enemyHp=Math.max(0,state.enemyHp-damage);animate('attack','.hero-combatant');animate('hit','.enemy-combatant');$('#hitFlash').classList.remove('show');void $('#hitFlash').offsetWidth;$('#hitFlash').classList.add('show');damageText(skill?`✦ ${damage}`:`${damage}`,67,34,skill?'crit':'');if(skill){$('#battleStage').insertAdjacentHTML('beforeend','<div class="skill-burst show" id="activeBurst"></div>');setTimeout(()=>$('#activeBurst')?.remove(),650)}
 renderBattle();if(state.enemyHp<=0){state.victory=true;renderBattle();return}setTimeout(()=>enemyRetaliate(e),420);save(true)}
