let state=baseState(),toastTimer;
function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function clone(v){return JSON.parse(JSON.stringify(v))}
function load(){try{const raw=localStorage.getItem(SAVE_KEY);if(!raw)return false;const saved=JSON.parse(raw);state={...baseState(),...saved,stats:{...baseState().stats,...saved.stats},equipment:{...saved.equipment},inventory:Array.isArray(saved.inventory)?saved.inventory:[],hero:saved.hero};if(!state.hero)return false;return true}catch(e){console.warn('Could not load local save',e);return false}}
function save(silent=false){try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));if(!silent)toast('Progress saved on this device.')}catch(e){toast('Save failed: device storage is unavailable.');console.error(e)}updateChrome()}
function toast(msg){const el=$('#toast');if(!el)return;el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function requiredXp(){return 70+state.level*35}
function heroStats(){const c=classes[state.hero?.class]||classes.Warrior, gear=Object.values(state.equipment).filter(Boolean).reduce((a,it)=>a+(Number(it.power)||0),0);return {hp:c.hp+state.level*16+state.stats.Vitality*22+gear*2,attack:c.attack+Math.floor(state.level*2.7)+state.stats.Might*3+gear,mana:c.mana+state.level*6+state.stats.Spirit*14}}
function currentEnemy(){const region=regions[state.region]||regions[0],isBoss=state.encounter===6,base=state.level;return {name:isBoss?region.boss:region.enemies[(state.encounter-1)%region.enemies.length],boss:isBoss,level:Math.max(1,base),desc:isBoss?'The guardian of this realm stands before you.':'A hungry thing stirs in the wilds.',max:Math.round((120+base*17)*(isBoss?2.5:1)),xp:Math.round((18+base*4)*(isBoss?3:1)),gold:Math.round((12+base*3)*(isBoss?2.5:1))}}
function startEncounter(){const enemy=currentEnemy();if(!state.enemyMax||state.victory){state.enemyMax=enemy.max;state.enemyHp=enemy.max;state.victory=false}state.heroHp=Math.max(1,Math.min(state.heroHp||heroStats().hp,heroStats().hp));state.mana=Math.max(0,Math.min(state.mana||heroStats().mana,heroStats().mana));renderBattle()}
function updateChrome(){if(!state.hero)return;const hs=heroStats(),hero=state.hero;$('#goldCount').textContent=state.gold;$('#gemCount').textContent=state.gems;$('#sidebarName').textContent=hero.name;$('#sidebarClass').textContent=`${hero.class.toUpperCase()} · LV ${state.level}`;$('#sidebarLevel').textContent=String(state.level).padStart(2,'0');$('#sidebarXp').style.width=`${Math.min(100,state.xp/requiredXp()*100)}%`;$('#sidebarCrest').textContent=hero.faction==='Angels'?'✧':'☾';$('#bagCount').textContent=state.inventory.length;$('#heroNameLabel').textContent=hero.name;$('#heroClassLabel').textContent=`${hero.appearance} ${hero.class.toUpperCase()}`;$('#battleHeroName').textContent=hero.name;$('#battleHeroClass').textContent=`LV ${state.level} · ${hero.class.toUpperCase()}`;$('#profileButton').textContent=$('#mobileProfile').textContent=hero.faction==='Angels'?'✧':'☾';$('#questProgress').style.width=`${Math.min(100,state.questKills/3*100)}%`;$('#questCount').textContent=`${Math.min(3,state.questKills)} / 3`;$('#gearPreview').innerHTML=slots.slice(0,4).map(s=>{const it=state.equipment[s];return `<div class="gear-row"><span>${slotIcons[s]}</span><b>${it?escapeHtml(it.name):`No ${s.toLowerCase()}`}</b></div>`}).join('')}
function renderBattle(){if(!state.hero)return;const r=regions[state.region]||regions[0],e=currentEnemy(),hs=heroStats();if(!state.enemyMax) {state.enemyMax=e.max;state.enemyHp=e.max}$('#regionHeading').textContent=r.name;$('#regionCaption').textContent=r.caption;$('#encounterCount').textContent=`ENCOUNTER ${String(state.encounter).padStart(2,'0')}`;$('#enemyNameLabel').textContent=e.name;$('#enemyIntroName').textContent=e.name;$('#enemyIntroDesc').textContent=e.desc;$('#enemyKind').textContent=e.boss?'REGIONAL GUARDIAN':'WILD · BEAST';$('#enemyTypeLabel').textContent=e.boss?'BOSS · GUARDIAN':'WILD · BEAST';$('#enemyLevel').textContent=`LV. ${e.level}`;$('#enemyHpText').textContent=`${Math.max(0,state.enemyHp)} / ${state.enemyMax}`;$('#enemyHpPercent').textContent=`${Math.round(Math.max(0,state.enemyHp)/state.enemyMax*100)}%`;$('#enemyHealthBar').style.width=`${Math.max(0,state.enemyHp)/state.enemyMax*100}%`;$('#heroHpText').textContent=`${Math.max(0,state.heroHp)} / ${hs.hp}`;$('#heroHealthBar').style.width=`${Math.max(0,state.heroHp)/hs.hp*100}%`;$('#manaBar').style.width=`${state.mana/hs.mana*100}%`;$('#manaText').textContent=`MANA ${state.mana} / ${hs.mana}`;$('#xpPreview').textContent=e.xp;$('#goldPreview').textContent=e.gold;$('#potionCount').textContent=`× ${state.potions}`;$('#skillOneName').textContent=classes[state.hero.class].skill1;$('#skillTwoName').textContent=classes[state.hero.class].skill2;$('#skillOne').disabled=state.victory||state.mana<12;$('#skillTwo').disabled=state.victory||state.mana<20;$('#attackButton').disabled=state.victory;$('#potionButton').disabled=state.victory||state.potions<1||state.heroHp>=hs.hp;$('#continueButton').classList.toggle('hidden',!state.victory);$('#continueButton').textContent=e.boss?'CLAIM VICTORY & CONTINUE →':'CLAIM VICTORY & CONTINUE →';updateChrome()}
function numberPop(text,cls=''){const layer=$('#damageLayer');const n=document.createElement('span');n.className=`damage-number ${cls}`;n.textContent=text;n.style.left=cls==='enemy-damage'?'23%':'73%';n.style.top=cls==='enemy-damage'?'54%':'43%';layer.appendChild(n);setTimeout(()=>n.remove(),1000)}
function animate(selector,cls){const el=$(selector);el.classList.remove(cls);void el.offsetWidth;el.classList.add(cls);setTimeout(()=>el.classList.remove(cls),450)}
function enemyTurn(){if(state.victory)return;const e=currentEnemy(),damage=Math.max(4,Math.round((7+e.level*2)*(e.boss?1.6:1)*(0.85+Math.random()*.3)));animate('#enemyFigure','attack');animate('#heroFigure','hurt');$('#hitFlash').classList.add('show');setTimeout(()=>$('#hitFlash').classList.remove('show'),300);state.heroHp=Math.max(0,state.heroHp-damage);numberPop(`−${damage}`,'enemy-damage');if(state.heroHp<=0){state.heroHp=Math.max(1,Math.round(heroStats().hp*.35));state.mana=Math.max(0,Math.round(state.mana*.5));toast('You were overcome, but the sanctuary restores you. The enemy remains.')}save(true);renderBattle()}
