function usePotion(){if(state.potions<1||state.victory)return;const hs=heroStats(),gain=Math.min(hs.hp-state.heroHp,Math.round(hs.hp*.38));if(gain<=0)return;state.potions--;state.heroHp+=gain;numberPop(`+${gain}`,'heal');toast(`Restored ${gain} health.`);save(true);renderBattle();setTimeout(enemyTurn,400)}
