function makeDrop(boss=false){const slot=slots[Math.floor(Math.random()*slots.length)],rarity=boss?'Rare':Math.random()<.16?'Uncommon':'Common',prefix={Weapon:['Briar','Dusk','Aether'],Head:['Mossbound','Warden','Moonlit'],Chest:['Grove','Runed','Ashen'],Hands:['Grips of','Gauntlets of','Wraps of'],Legs:['Treads of','Greaves of','Leggings of'],Feet:['Boots of','Steps of','Sandals of'],Accessory:['Charm of','Pendant of','Signet of'],Wings:['Wings of','Veil of','Feathers of'],Relic:['Relic of','Shard of','Idol of']}[slot],names={Weapon:['Thorn','the First Dawn','the Wild Hunt'],Head:['the Old Glade','the Watcher','Dawn'],Chest:['the Briarheart','the Warden','the Deepwood'],Hands:['the Wilds','Dusk','the Stalker'],Legs:['the Hunt','the Glade','the Wanderer'],Feet:['the Silent Path','the Grove','the Gale'],Accessory:['Wild Grace','the Veil','the Moon'],Wings:['the First Light','the Glade','the Veil'],Relic:['the Ancients','the First Dawn','the Wilds']}[slot],power=1+(state.level>4?Math.floor(state.level/4):0)+(boss?2:0);return {id:`it-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,name:`${prefix[Math.floor(Math.random()*prefix.length)]} ${names[Math.floor(Math.random()*names.length)]}`,slot,rarity,power,bonus:`+${power} ${slot==='Weapon'?'ATK':'POWER'}`}}
function ensureModal(html){$('#modalContent').innerHTML=html;$('#modalBackdrop').classList.add('open')}
function closeModal(){$('#modalBackdrop').classList.remove('open')}
