function equipItem(item){
 if(!item||!slots.includes(item.slot))return;
 const previous=state.equipment[item.slot];
 state.inventory=state.inventory.filter(it=>it.id!==item.id);
 if(previous)state.inventory.push(previous);
 state.equipment[item.slot]=item;
 state.heroHp=Math.min(state.heroHp,heroStats().hp);
 save(true);renderPage('inventory');renderBattle();toast(`${item.name} equipped.`)
}
function showItem(item){
 if(!item)return;
 const equipped=state.equipment[item.slot]?.id===item.id;
 ensureModal(`<h2 style="color:${rarityColor[item.rarity]||'#ddd'}">${escapeHtml(item.name)}</h2><p class="subhead">${escapeHtml(item.rarity)} ${escapeHtml(item.slot)} · ${escapeHtml(item.bonus||`+${item.power} POWER`)}<br>Equipment power contributes to your combat stats.</p><div class="modal-footer"><button class="secondary-button" data-modal-close>BACK</button><button class="primary-button" id="equipItemButton" ${equipped?'disabled':''}>${equipped?'EQUIPPED':'EQUIP ITEM'}</button></div>`);
 $('#equipItemButton').onclick=()=>{closeModal();equipItem(item)};
}
function showFusion(){
 const groups=new Map();
 state.inventory.forEach(item=>{
  const key=[item.slot,item.name,item.rarity,item.power].join('|');
  if(!groups.has(key))groups.set(key,[]);
  groups.get(key).push(item)
 });
 const candidates=[...groups.values()].filter(group=>group.length>=4);
 const content=candidates.length?candidates.map((group,i)=>`<button class="item-row fusion-choice" data-fusion="${i}" style="width:100%;text-align:left;background:transparent;color:inherit;border:0;cursor:pointer"><span class="item-icon">✦</span><span class="grow"><strong>${escapeHtml(group[0].name)}</strong><small>${group.length} identical · ${escapeHtml(group[0].rarity)} · ${escapeHtml(group[0].slot}</small></span><b style="color:#d8bc83">FUSE 4</b></button>`).join(''):'<div class="empty-state"><b>No fusion set yet.</b>Collect four matching items with the same name, slot, rarity, and power to fuse them into a stronger piece.</div>';
 ensureModal(`<h2>Fuse equipment</h2><p class="subhead">Combine four identical items into one piece of the next rarity, with increased power. Fusing is permanent.</p>${content}<div class="modal-footer"><button class="secondary-button" data-modal-close>DONE</button></div>`);
 $$('.fusion-choice',$('#modalContent')).forEach((button,index)=>button.onclick=()=>fuseItems(candidates[index]));
}
function fuseItems(group){
 if(!group||group.length<4)return;
 const item=group[0],rarities=['Common','Uncommon','Rare','Epic','Legendary'],rank=rarities.indexOf(item.rarity),next=rarities[Math.min(rank+1,rarities.length-1)];
 const consumed=new Set(group.slice(0,4).map(x=>x.id));
 state.inventory=state.inventory.filter(x=>!consumed.has(x.id));
 state.inventory.push({...clone(item),id:`it-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,rarity:next,power:(Number(item.power)||1)+1,bonus:`+${(Number(item.power)||1)+1} ${item.slot==='Weapon'?'ATK':'POWER'}`});
 save(true);closeModal();renderPage('inventory');renderBattle();toast(`Fusion complete: ${next} ${item.slot}.`)
}

