function updateChrome(){if(!state.hero)return;const hs=heroStats(),hero=state.hero;$('#goldCount').textContent=state.gold;$('#gemCount').textContent=state.gems;$('#sidebarName').textContent=hero.name;$('#sidebarClass').textContent=`${hero.class.toUpperCase()} · LV ${state.level}`;$('#sidebarLevel').textContent=String(state.level).padStart(2,'0');$('#sidebarXp').style.width=`${Math.min(100,state.xp/requiredXp()*100)}%`;$('#sidebarCrest').textContent=hero.faction==='Angels'?'✧':'☾';$('#bagCount').textContent=state.inventory.length;$('#heroNameLabel').textContent=hero.name;$('#heroClassLabel').textContent=`${hero.appearance} ${hero.class.toUpperCase()}`;$('#battleHeroName').textContent=hero.name;$('#battleHeroClass').textContent=`LV ${state.level} · ${hero.class.toUpperCase()}`;$('#profileButton').textContent=$('#mobileProfile').textContent=hero.faction==='Angels'?'✧':'☾';$('#questProgress').style.width=`${Math.min(100,state.questKills/3*100)}%`;$('#questCount').textContent=`${Math.min(3,state.questKills)} / 3`;$('#gearPreview').innerHTML=slots.slice(0,4).map(s=>{const it=state.equipment[s];return `<div class="gear-row"><span>${slotIcons[s]}</span><b>${it?escapeHtml(it.name):`No ${s.toLowerCase()}`}</b></div>`}).join('')}
function renderBattle(){if(!state.hero)return;const r=regions[state.region]||regions[0],e=currentEnemy(),hs=heroStats();if(!state.enemyMax) {state.enemyMax=e.max;state.enemyHp=e.max}$('#regionHeading').textContent=r.name;$('#regionCaption').textContent=r.caption;$('#encounterCount').textContent=`ENCOUNTER ${String(state.encounter).padStart(2,'0')}`;$('#enemyNameLabel').textContent=e.name;$('#enemyIntroName').textContent=e.name;$('#enemyIntroDesc').textContent=e.desc;$('#enemyKind').textContent=e.boss?'REGIONAL GUARDIAN':'WILD · BEAST';$('#enemyTypeLabel').textContent=e.boss?'BOSS · GUARDIAN':'WILD · BEAST';$('#enemyLevel').textContent=`LV. ${e.level}`;$('#enemyHpText').textContent=`${Math.max(0,state.enemyHp)} / ${state.enemyMax}`;$('#enemyHpPercent').textContent=`${Math.round(Math.max(0,state.enemyHp)/state.enemyMax*100)}%`;$('#enemyHealthBar').style.width=`${Math.max(0,state.enemyHp)/state.enemyMax*100}%`;$('#heroHpText').textContent=`${Math.max(0,state.heroHp)} / ${hs.hp}`;$('#heroHealthBar').style.width=`${Math.max(0,state.heroHp)/hs.hp*100}%`;$('#manaBar').style.width=`${state.mana/hs.mana*100}%`;$('#manaText').textContent=`MANA ${state.mana} / ${hs.mana}`;$('#xpPreview').textContent=e.xp;$('#goldPreview').textContent=e.gold;$('#potionCount').textContent=`× ${state.potions}`;$('#skillOneName').textContent=classes[state.hero.class].skill1;$('#skillTwoName').textContent=classes[state.hero.class].skill2;$('#skillOne').disabled=state.victory||actionPending||state.mana<12;$('#skillTwo').disabled=state.victory||actionPending||state.mana<20;$('#attackButton').disabled=state.victory||actionPending;$('#potionButton').disabled=state.victory||actionPending||state.potions<1||state.heroHp>=hs.hp;$('#continueButton').classList.toggle('hidden',!state.victory);$('#continueButton').textContent=e.boss?'CLAIM VICTORY & CONTINUE →':'CLAIM VICTORY & CONTINUE →';updateChrome()}
function numberPop(text,cls=''){const layer=$('#damageLayer');const n=document.createElement('span');n.className=`damage-number ${cls}`;n.textContent=text;n.style.left=cls==='enemy-damage'?'23%':'73%';n.style.top=cls==='enemy-damage'?'54%':'43%';layer.appendChild(n);setTimeout(()=>n.remove(),1000)}
function animate(selector,cls){const el=$(selector);el.classList.remove(cls);void el.offsetWidth;el.classList.add(cls);setTimeout(()=>el.classList.remove(cls),450)}
function enemyTurn(){if(state.victory||!state.hero)return;const e=currentEnemy(),damage=Math.max(4,Math.round((7+e.level*2)*(e.boss?1.6:1)*(0.85+Math.random()*.3)));animate('#enemyFigure','attack');animate('#heroFigure','hurt');$('#hitFlash').classList.add('show');setTimeout(()=>$('#hitFlash').classList.remove('show'),300);state.heroHp=Math.max(0,state.heroHp-damage);numberPop(`−${damage}`,'enemy-damage');if(state.heroHp<=0){state.heroHp=Math.max(1,Math.round(heroStats().hp*.35));state.mana=Math.max(0,Math.round(state.mana*.5));toast('You were overcome, but the sanctuary restores you. The enemy remains.')}save(true);renderBattle();actionPending=false}
function doAttack(mult=1,cost=0){if(state.victory||state.heroHp<=0||actionPending)return;if(state.mana<cost){toast('Not enough mana.');return}actionPending=true;state.mana-=cost;const hs=heroStats(),damage=Math.max(1,Math.round((hs.attack*mult)*(0.85+Math.random()*.3)));animate('#heroFigure','attack');animate('#enemyFigure','hit');$('#hitFlash').classList.add('show');setTimeout(()=>$('#hitFlash').classList.remove('show'),300);state.enemyHp=Math.max(0,state.enemyHp-damage);numberPop(`−${damage}`,Math.random()<.12?'crit':'');if(state.enemyHp===0){actionPending=false;state.victory=true;state.kills++;if(state.region===0)state.questKills=Math.min(3,state.questKills+1);toast(`${currentEnemy().name} defeated. Claim your victory.`);save(true);renderBattle();return}save(true);renderBattle();setTimeout(enemyTurn,440)}
function usePotion(){if(state.potions<1||state.victory||actionPending)return;actionPending=true;const hs=heroStats(),gain=Math.min(hs.hp-state.heroHp,Math.round(hs.hp*.38));if(gain<=0){actionPending=false;return}state.potions--;state.heroHp+=gain;numberPop(`+${gain}`,'heal');toast(`Restored ${gain} health.`);save(true);renderBattle();setTimeout(enemyTurn,400)}
function rewardVictory(){if(!state.victory)return;const e=currentEnemy();state.xp+=e.xp;state.gold+=e.gold;if(e.boss){state.bosses.push(`${state.region}:${e.name}`);if(state.region===state.unlocked&&state.unlocked<regions.length-1)state.unlocked++;}if(Math.random()<.42||e.boss)state.inventory.push(makeDrop(e.boss));while(state.xp>=requiredXp()){state.xp-=requiredXp();state.level++;state.points+=3;state.heroHp=heroStats().hp;state.mana=heroStats().mana;toast(`Level up! You reached level ${state.level}.`)}state.encounter=e.boss?1:state.encounter+1;state.enemyMax=0;state.enemyHp=0;state.victory=false;state.heroHp=Math.min(heroStats().hp,state.heroHp+Math.round(heroStats().hp*.18));state.mana=Math.min(heroStats().mana,state.mana+10);save(true);renderBattle();if($('.screen.active')?.id==='screen-quests')renderPage('quests');toast(`Victory claimed: ${e.xp} XP and ${e.gold} gold.`)}
function makeDrop(boss=false){const slot=slots[Math.floor(Math.random()*slots.length)],rarity=boss?'Rare':Math.random()<.16?'Uncommon':'Common',prefix={Weapon:['Briar','Dusk','Aether'],Head:['Mossbound','Warden','Moonlit'],Chest:['Grove','Runed','Ashen'],Hands:['Grips of','Gauntlets of','Wraps of'],Legs:['Treads of','Greaves of','Leggings of'],Feet:['Boots of','Steps of','Sandals of'],Accessory:['Charm of','Pendant of','Signet of'],Wings:['Wings of','Veil of','Feathers of'],Relic:['Relic of','Shard of','Idol of']}[slot],names={Weapon:['Thorn','the First Dawn','the Wild Hunt'],Head:['the Old Glade','the Watcher','Dawn'],Chest:['the Briarheart','the Warden','the Deepwood'],Hands:['the Wilds','Dusk','the Stalker'],Legs:['the Hunt','the Glade','the Wanderer'],Feet:['the Silent Path','the Grove','the Gale'],Accessory:['Wild Grace','the Veil','the Moon'],Wings:['the First Light','the Glade','the Veil'],Relic:['the Ancients','the First Dawn','the Wilds']}[slot],power=1+(state.level>4?Math.floor(state.level/4):0)+(boss?2:0);return {id:`it-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,name:`${prefix[Math.floor(Math.random()*prefix.length)]} ${names[Math.floor(Math.random()*names.length)]}`,slot,rarity,power,bonus:`+${power} ${slot==='Weapon'?'ATK':'POWER'}`}}
function ensureModal(html){$('#modalContent').innerHTML=html;$('#modalBackdrop').classList.add('open')}
function closeModal(){$('#modalBackdrop').classList.remove('open')}
function bindEvents(){
 $$('[data-screen]').forEach(button=>button.addEventListener('click',()=>showScreen(button.dataset.screen)));
 $('#attackButton').onclick=()=>doAttack();$('#skillOne').onclick=()=>{animate('#heroFigure','skill-burst');doAttack(2,12)};$('#skillTwo').onclick=()=>{animate('#heroFigure','skill-burst');doAttack(3,20)};
 $('#potionButton').onclick=usePotion;$('#continueButton').onclick=rewardVictory;$('#saveButton').onclick=()=>save();
 $('#menuToggle').onclick=()=>$('.sidebar').classList.toggle('open');
 $('#profileButton').onclick=$('#mobileProfile').onclick=()=>showScreen('character');
 $('#soundButton').onclick=()=>{state.sound=!state.sound;$('#soundButton').classList.toggle('muted',!state.sound);save(true);toast(state.sound?'Sound enabled.':'Sound muted.')};
 $('#modalBackdrop').addEventListener('click',event=>{if(event.target.id==='modalBackdrop'||event.target.closest('[data-modal-close]'))closeModal()});
 document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal();if(event.key===' '&&!event.repeat&&$('.screen.active')?.id==='screen-battle'&&!$('#modalBackdrop').classList.contains('open')){event.preventDefault();doAttack()}});
}
function boot(){
 bindEvents();
 if(load()){
  state.region=Math.max(0,Math.min(regions.length-1,Number(state.region)||0));state.unlocked=Math.max(0,Math.min(regions.length-1,Number(state.unlocked)||0));
  state.level=Math.max(1,Number(state.level)||1);state.encounter=Math.max(1,Number(state.encounter)||1);
  state.enemyHp=Math.max(0,Number(state.enemyHp)||0);state.enemyMax=Math.max(0,Number(state.enemyMax)||0);
  state.inventory=state.inventory.filter(item=>item&&item.id&&slots.includes(item.slot));
  Object.keys(state.equipment).forEach(slot=>{if(!slots.includes(slot)||!state.equipment[slot])delete state.equipment[slot]});
  if(!classes[state.hero.class])state.hero.class='Warrior';
  if(!['Angels','Demons'].includes(state.hero.faction))state.hero.faction='Angels';
  if(!['Male','Female'].includes(state.hero.appearance))state.hero.appearance='Male';
  state.heroHp=Math.max(1,Math.min(Number(state.heroHp)||heroStats().hp,heroStats().hp));state.mana=Math.max(0,Math.min(Number(state.mana)||heroStats().mana,heroStats().mana));
  if(state.victory&&state.enemyHp===0)state.enemyMax=currentEnemy().max;
  updateChrome();renderBattle();openWelcome()
 }else openCreator();
}

function showScreen(name){$$('.screen').forEach(el=>el.classList.toggle('active',el.id===`screen-${name}`));$$('[data-screen]').forEach(el=>el.classList.toggle('active',el.dataset.screen===name));if(name!=='battle')renderPage(name);if(window.innerWidth<=700)document.querySelector('.sidebar')?.classList.remove('open');window.scrollTo({top:0,behavior:'smooth'})}
function pageHead(kicker,title,desc){return `<header class="page-header"><div class="eyebrow">${kicker}</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</header>`}
function renderPage(which){const el=$(`#screen-${which}`);if(!el)return;switch(which){case'world':el.innerHTML=pageHead('AETHERIA · THE KNOWN REALMS','World map','Eight realms lie beyond Greendale. Each region unlocks after the previous boss is defeated.')+`<div class="card-grid">${regions.map((r,i)=>{const unlocked=i<=state.unlocked;return `<article class="panel-card region-card ${i===state.region?'selected':''} ${!unlocked?'locked':''}" data-region="${i}" style="--region-color:${r.tone};--region-glow:${r.tone}"><span class="region-mark">${r.icon}</span><span class="region-state">${i===state.region?'CURRENT':unlocked?'UNLOCKED':`LV ${r.unlock} · LOCKED`}</span><h3>${r.name}</h3><p>${r.desc}</p></article>`}).join('')}</div><div class="map-note"><b style="color:#dfc58e">Expedition:</b> Defeat the regional boss to open the next realm. Greendale's boss appears at encounter 6. Your progress is saved locally on this device.</div>`;$$('[data-region]',el).forEach(card=>card.addEventListener('click',()=>{const ix=+card.dataset.region;if(ix>state.unlocked){toast(`Defeat the ${regions[ix-1].boss} to unlock this realm.`);return}state.region=ix;state.encounter=1;state.enemyMax=0;state.victory=false;state.heroHp=Math.min(state.heroHp,heroStats().hp);save(true);showScreen('battle');renderBattle();toast(`${regions[ix].name} awaits.`)}));break;
case'character':{const hs=heroStats();el.innerHTML=pageHead('YOUR LEGEND · CHARACTER','Character','A single hero, bound by your choices. Spend attribute points to shape your build.')+`<div class="panel-card stat-overview"><div class="portrait-card">${state.hero.faction==='Angels'?'✧':'☾'}</div><div class="stat-copy"><h2>${escapeHtml(state.hero.name)}</h2><span class="muted">${state.hero.appearance} ${state.hero.class} · ${state.hero.faction} · Level ${state.level}</span><div class="level-line"><span>EXPERIENCE</span><span>${state.xp} / ${requiredXp()}</span></div><div class="bar"><i style="width:${Math.min(100,state.xp/requiredXp()*100)}%"></i></div></div></div><div class="stat-grid"><div class="stat-tile"><span>HEALTH</span><b>${hs.hp}</b></div><div class="stat-tile"><span>ATTACK</span><b>${hs.attack}</b></div><div class="stat-tile"><span>MANA</span><b>${hs.mana}</b></div><div class="stat-tile"><span>ENEMIES</span><b>${state.kills}</b></div><div class="stat-tile"><span>ATTRIBUTE POINTS</span><b>${state.points}</b></div><div class="stat-tile"><span>BOSSES</span><b>${state.bosses.length}</b></div></div><div class="panel-card" style="margin-top:12px"><div class="rail-title">ATTRIBUTES <span>${state.points} POINTS AVAILABLE</span></div>${Object.entries(state.stats).map(([name,value])=>`<div class="attribute-row"><span>${name==='Might'?'⚔':name==='Vitality'?'♥':'✧'}</span><div class="grow"><strong>${name}</strong><small>${name==='Might'?'Increases attack power':name==='Vitality'?'Increases maximum health':'Increases maximum mana'}</small></div><b style="color:#dfcfac;font:15px var(--serif)">${value}</b><button class="small-action" data-stat="${name}" ${state.points<1?'disabled':''}>+1</button></div>`).join('')}</div><div class="panel-card" style="margin-top:12px"><div class="rail-title">COMBAT SKILLS</div><div class="item-row"><span class="item-icon">✧</span><div class="grow"><strong>${classes[state.hero.class].skill1}</strong><small>12 mana · deal 2× attack damage · Available now</small></div><span style="color:#d4bd90;font-size:8px">ACTIVE</span></div><div class="item-row"><span class="item-icon">☄</span><div class="grow"><strong>${classes[state.hero.class].skill2}</strong><small>20 mana · deal 3× attack damage · Available now</small></div><span style="color:#d4bd90;font-size:8px">ACTIVE</span></div></div>`;$$('[data-stat]',el).forEach(btn=>btn.onclick=()=>{if(state.points<=0)return;state.stats[btn.dataset.stat]++;state.points--;state.heroHp=heroStats().hp;state.mana=heroStats().mana;save(true);renderPage('character');renderBattle();toast(`${btn.dataset.stat} increased.`)});break}
case'inventory':renderInventory(el);break;
case'quests':el.innerHTML=pageHead('FIELD NOTES · PERSONAL JOURNAL','Journal','A few steps into a much longer story. Complete the Greendale hunt to earn a small gem bounty.')+`<div class="panel-card"><div class="quest-row"><span class="item-icon">⚔</span><div class="grow"><strong>The Glade Stirs</strong><small>Defeat 3 creatures in Greendale.</small></div><span style="font-size:9px;color:#dfc58e">${Math.min(3,state.questKills)} / 3</span></div><div class="bar"><i style="width:${Math.min(100,state.questKills/3*100)}%"></i></div>${state.questKills>=3?`<button class="small-action" style="margin-top:13px" id="claimQuest" ${state.questClaimed?'disabled':''}>${state.questClaimed?'REWARD CLAIMED':'CLAIM 5 GEMS'}</button>`:''}</div><div class="panel-card" style="margin-top:12px"><div class="rail-title">EXPEDITION RECORD</div><div class="quest-row"><span class="item-icon">⌖</span><div class="grow"><strong>Realms discovered</strong><small>${state.unlocked+1} of ${regions.length}</small></div></div><div class="quest-row"><span class="item-icon">♜</span><div class="grow"><strong>Bosses defeated</strong><small>${state.bosses.length} regional ${state.bosses.length===1?'guardian':'guardians'}</small></div></div><div class="quest-row"><span class="item-icon">✦</span><div class="grow"><strong>Account & cloud save</strong><small>Not connected — local save only</small></div></div></div>`;if($('#claimQuest',el))$('#claimQuest',el).onclick=()=>{if(state.questClaimed)return;state.questClaimed=true;state.gems+=5;save(true);renderPage('quests');toast('Quest reward claimed: 5 gems.')};break;
case'shop':el.innerHTML=pageHead('SANCTUARY · COSMETIC COLLECTION','Cosmetics','Style your legend with earnable cosmetics. No gameplay power is sold here.')+`<div class="card-grid">${[{icon:'♧',name:'Greendale Warden',desc:'A moss-threaded travel cloak.',cost:40,currency:'gold'},{icon:'✧',name:'Dawnlit Wings',desc:'A luminous cosmetic wing trail.',cost:12,currency:'gems'},{icon:'❀',name:'Silverleaf Crown',desc:'A crown woven from moonlit leaves.',cost:10,currency:'gems'},{icon:'⚡',name:'Aether Weapon Glow',desc:'A soft, starlit blade effect.',cost:55,currency:'gold'}].map((c,i)=>`<article class="panel-card shop-card"><div><div class="cosmetic-art">${c.icon}</div><h3>${c.name}</h3><p>${c.desc}</p></div><button class="small-action" data-cosmetic="${i}" data-cost="${c.cost}" data-currency="${c.currency}" ${state.cosmetics.includes(i)?'disabled':''}>${state.cosmetics.includes(i)?'OWNED':`◈ ${c.cost} ${c.currency.toUpperCase()}`}</button></article>`).join('')}</div><div class="online-banner"><b>Real-money purchases are not available.</b> Google Play Billing has not been integrated. No purchase will be simulated or charged. Cosmetics shown here use earnable in-game currency only.</div>`;$$('[data-cosmetic]',el).forEach(b=>b.onclick=()=>{const cost=+b.dataset.cost,curr=b.dataset.currency;if(state[curr]<cost){toast(`Not enough ${curr}.`);return}state[curr]-=cost;state.cosmetics.push(+b.dataset.cosmetic);save(true);renderPage('shop');toast('Cosmetic unlocked!')});break}}
function renderInventory(el){const items=state.inventory;el.innerHTML=pageHead('SANCTUARY · YOUR BELONGINGS','Inventory',`${items.length} items · Equipment, drops, and materials gathered on your journey.`)+`<div class="inventory-toolbar">${['All','Weapon','Armor','Accessory'].map(f=>`<button class="filter-chip ${state.filter===f?'active':''}" data-filter="${f}">${f.toUpperCase()}</button>`).join('')}<button class="filter-chip" id="fusionButton">FUSE 4 IDENTICAL</button></div><div class="equipment-layout"><div><div class="rail-title">EQUIPPED GEAR <span>9 SLOTS</span></div><div class="equipment-slots">${slots.map(s=>{const it=state.equipment[s];return `<div class="equip-slot ${it?'filled':''}" data-equip-slot="${s}"><span class="slot-symbol">${slotIcons[s]}</span><span><small>${s.toUpperCase()}</small><b style="color:${it?rarityColor[it.rarity]:'#9a989b'}">${it?escapeHtml(it.name):'Empty slot'}</b></span></div>`}).join('')}</div></div><div><div class="rail-title">BACKPACK <span>${items.length} ITEMS</span></div>${items.length?`<div class="inventory-grid">${items.filter(it=>state.filter==='All'||it.slot===state.filter||(state.filter==='Armor'&&['Head','Chest','Hands','Legs','Feet'].includes(it.slot))||(state.filter==='Accessory'&&['Accessory','Wings','Relic'].includes(it.slot))).map((it)=>`<div class="inventory-item" data-item="${it.id}" style="--rarity:${rarityColor[it.rarity]||'#aaa'}"><span class="rarity-label">${it.rarity.toUpperCase()}</span><div class="item-symbol">${slotIcons[it.slot]||'✧'}</div><b>${escapeHtml(it.name)}</b><small>${it.slot} · ${it.bonus}</small></div>`).join('')||'<div class="empty-state">No items in this category.</div>'}</div>`:'<div class="empty-state"><b>Your pack is quiet… for now.</b>Defeat creatures for equipment drops. Some drops are uncommon; boss rewards are better.</div>'}</div></div>`;
$$('[data-filter]',el).forEach(b=>b.onclick=()=>{state.filter=b.dataset.filter;renderInventory(el)});$$('[data-item]',el).forEach(card=>card.onclick=()=>showItem(items.find(x=>x.id===card.dataset.item)));$$('[data-equip-slot]',el).forEach(card=>card.onclick=()=>{const slot=card.dataset.equipSlot;if(state.equipment[slot]){state.inventory.push(state.equipment[slot]);delete state.equipment[slot];save(true);renderPage('inventory');renderBattle();toast(`${slot} unequipped.`)}else{const found=state.inventory.find(it=>it.slot===slot);if(found)equipItem(found);else toast(`No ${slot.toLowerCase()} to equip.`)}});$('#fusionButton',el).onclick=showFusion}

function equipItem(item){
 if(!item||!slots.includes(item.slot))return;
 const previous=state.equipment[item.slot];
 state.inventory=state.inventory.filter(it=>it.id!==item.id);
 if(previous)state.inventory.push(previous);
 state.equipment[item.slot]=item;
 state.heroHp=Math.min(state.heroHp,heroStats().hp);
 save(true);renderPage('inventory');renderBattle();toast(`${item.name} equipped.`)
}
function showItem(item){
 if(!item)return;
 const equipped=state.equipment[item.slot]?.id===item.id;
 ensureModal(`<h2 style="color:${rarityColor[item.rarity]||'#ddd'}">${escapeHtml(item.name)}</h2><p class="subhead">${escapeHtml(item.rarity)} ${escapeHtml(item.slot)} · ${escapeHtml(item.bonus||`+${item.power} POWER`)}<br>Equipment power contributes to your combat stats.</p><div class="modal-footer"><button class="secondary-button" data-modal-close>BACK</button><button class="primary-button" id="equipItemButton" ${equipped?'disabled':''}>${equipped?'EQUIPPED':'EQUIP ITEM'}</button></div>`);

